def SortLength():
Swap = True
Count = 0
while(Count < 14 and Swap):
Swap = False
for y in range(14):
     if(len(DataArray[y]) > len(DataArray[y+1])):
          DataArray[y], DataArray[y+1] = DataArray[y+1], DataArray[y]
          Swap = True
Count = Count + 1
