public static void SortLength(){
String Temp;
Boolean Swap = true;
Integer Count = 0;
while(Count < 14 && Swap){
Swap = false;
for(Integer y = 0; y < 14; y++){
     if(DataArray[y].length() > DataArray[y+1].length()){
          Temp = DataArray[y];
          DataArray[y] = DataArray[y+1];
          DataArray[y+1] = Temp;
          Swap = true;
     }
}
Count++;
}
}

