 •   … repeating until leaf node found …
 •   … updating correct parent node pointer to new node
Example program code
Python
def AddNode(NodeData):
global FirstFreeNodePointer
global TreeRootPointer
if FirstFreeNodePointer <= 99:
BinaryTree[FirstFreeNodePointer][0] = -1
BinaryTree[FirstFreeNodePointer][1] = NodeData
BinaryTree[FirstFreeNodePointer][2] = -1
if TreeRootPointer == -1:
     TreeRootPointer = 0
else:
     Placed = False
     CurrentNode = TreeRootPointer
     while Placed == False:
          if NodeData < BinaryTree[CurrentNode][1]:
              if BinaryTree[CurrentNode][0] == -1:
                   BinaryTree[CurrentNode][0] = FirstFreeNodePointer
                   Placed = True
              else:
                   CurrentNode = BinaryTree[CurrentNode][0]
          else:
              if BinaryTree[CurrentNode][2] == -1:
                   BinaryTree[CurrentNode][2] = FirstFreeNodePointer
                   Placed = True
              else:
                   CurrentNode = BinaryTree[CurrentNode][2]
FirstFreeNodePointer = FirstFreeNodePointer + 1
else:
print("The tree is full")
